begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local storage.allow_delete_query='true';
insert into public.parties(id,name)values('66000000-0000-4000-8000-000000000001','Ticket06 rollback fixture');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('66000000-0000-4000-8000-000000000011','ticket06-dm@verification.test','{}','{}'),('66000000-0000-4000-8000-000000000012','ticket06-player@verification.test','{}','{}');
insert into public.party_members(party_id,user_id,role)values('66000000-0000-4000-8000-000000000001','66000000-0000-4000-8000-000000000011','dungeon-master'),('66000000-0000-4000-8000-000000000001','66000000-0000-4000-8000-000000000012','player');
create function pg_temp.intent(suffix text default '002')returns jsonb language sql as $$select jsonb_build_object('requestId','66000000-0000-4000-8000-000000000'||suffix,'familyId','66000000-0000-4000-8000-000000000003','expectedVersion',0,'kind','generate','title','Fixture generation','instructions','Sea cave','document','{"columns":8,"rows":6,"feetPerSquare":5,"terrain":[],"edges":[]}'::jsonb);$$;
set local "request.jwt.claim.role"='service_role';
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent(),'live')$$,'P0001','Generation disabled','live disabled without configuration');
insert into public.party_map_generation_settings(party_id,fixture_enabled,quota)values('66000000-0000-4000-8000-000000000001',true,5);
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent(),'live')$$,'P0001','Generation disabled','fixture switch never enables live');
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000012',pg_temp.intent(),'fixture')$$,'42501','Dungeon Master access required','genuine Player membership denied reservation');
select is(public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent(),'fixture')->>'state','queued','DM reserves fixture job');
select is(public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent(),'fixture')->>'state','queued','duplicate submission reconciles original job');
select is((select count(*)from public.party_map_generation_jobs),1::bigint,'one durable record for duplicate request');
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent()||'{"instructions":"different"}', 'fixture')$$,'P0001','Request identity already used','different content cannot reuse request');
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent('004'),'fixture')$$,'P0001','Generation already active','concurrency limit enforced before provider');
select is(public.transition_map_generation('66000000-0000-4000-8000-000000000002',1,'running','{"submissionToken":"66000000-0000-4000-8000-000000000020"}')->>'submission_token','66000000-0000-4000-8000-000000000020','atomic claim records winner token');
select is(public.transition_map_generation('66000000-0000-4000-8000-000000000002',1,'running','{"submissionToken":"66000000-0000-4000-8000-000000000021"}')->>'submission_token','66000000-0000-4000-8000-000000000020','CAS loser cannot acquire submission');
select is(public.transition_map_generation('66000000-0000-4000-8000-000000000002',2,'uncertain','{"code":"submission-unknown"}')->>'state','uncertain','unknown outcome remains durable');
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent('004'),'fixture')$$,'P0001','Generation already active','uncertain outcome retains concurrency');
select is(public.transition_map_generation('66000000-0000-4000-8000-000000000002',3,'cancelled','{}')->>'state','cancelled','cancel durable uncertain job');
select is(public.transition_map_generation('66000000-0000-4000-8000-000000000002',4,'awaiting-client-output','{}')->>'state','cancelled','late provider result cannot resurrect cancellation');
select throws_ok($$select public.complete_map_generation('66000000-0000-4000-8000-000000000002',4,'{}','{}','{}')$$,'P0001','Job/proof/object binding rejected','cancelled job cannot attach');
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent('004'),'fixture')$$,'P0001','Generation already active','cancelled in-flight work retains slot until deadline');
update public.party_map_generation_jobs set deadline=now()-interval '1 second' where id='66000000-0000-4000-8000-000000000002';
select lives_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent('004'),'fixture')$$,'fresh job after original bounded provider deadline');
select public.transition_map_generation('66000000-0000-4000-8000-000000000004',1,'running','{"submissionToken":"66000000-0000-4000-8000-000000000022"}');
create function pg_temp.proof()returns jsonb language sql as $$ select jsonb_build_object('requestId','66000000-0000-4000-8000-000000000004','jobId','66000000-0000-4000-8000-000000000004','partyId','66000000-0000-4000-8000-000000000001','familyId','66000000-0000-4000-8000-000000000003','origin','generated','sourceObjectId','66000000-0000-4000-8000-000000000004','sourceDigest',repeat('b',64),'candidateDigest',repeat('b',64),'candidateObjectId','66000000-0000-4000-8000-000000000004','parentVersionId',null,'expectedVersion',0,'verifierVersion','map-png-rgba-v1','expectedRgbaDigest',repeat('a',64),'expiresAt',extract(epoch from now())*1000+86400000,'pixelWidth',1024,'pixelHeight',1024,'region','{"x":0,"y":0,"width":1024,"height":1024}'::jsonb);$$;
select public.transition_map_generation('66000000-0000-4000-8000-000000000004',2,'awaiting-client-output',jsonb_build_object('candidate',jsonb_build_object('objectId','66000000-0000-4000-8000-000000000004','size',68,'digest',repeat('b',64)),'proof',pg_temp.proof(),'provisional',jsonb_build_object('objectId','66000000-0000-4000-8000-000000000004','size',68,'digest',repeat('c',64))));
insert into storage.objects(bucket_id,name,metadata)values('party-handouts','66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000004','{"size":68,"mimetype":"image/png"}'),('private-map-generation','66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000004','{"size":68,"mimetype":"image/png"}'),('party-handouts','66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000090','{"size":68,"mimetype":"image/png"}');
select throws_ok($$update storage.objects set metadata='{"size":1}' where name='66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000004' and bucket_id='party-handouts'$$,'P0001','Generation object is retained','provisional cannot swap metadata');
select throws_ok($$delete from storage.objects where name='66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000004' and bucket_id='party-handouts'$$,'P0001','Generation object is retained','unattached provisional cannot be deleted');
select throws_ok($$update storage.objects set metadata='{"size":1}' where bucket_id='private-map-generation'$$,'P0001','Generation objects are immutable','raw candidate cannot swap metadata');
update storage.objects set metadata='{"size":69,"mimetype":"image/png"}' where name='66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000090';
select is((select metadata->>'size' from storage.objects where name='66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000090'),'69','unrelated storage update remains unaffected');
create function pg_temp.background()returns jsonb language sql as $$select jsonb_build_object('object_id','66000000-0000-4000-8000-000000000004','size',68,'digest',repeat('c',64),'mime','image/png','x',1,'y',0,'width',6,'height',6,'pixelWidth',1024,'pixelHeight',1024);$$;
create function pg_temp.verified()returns jsonb language sql as $$select jsonb_build_object('kind','verified','outputDigest',repeat('c',64),'actualRgbaDigest',repeat('a',64));$$;
select throws_ok($$select public.complete_map_generation('66000000-0000-4000-8000-000000000004',3,pg_temp.proof()||'{"expectedVersion":9}',pg_temp.verified(),pg_temp.background())$$,'P0001','Job/proof/object binding rejected','proof swap rejected atomically');
select throws_ok($$select public.complete_map_generation('66000000-0000-4000-8000-000000000004',3,pg_temp.proof(),pg_temp.verified()||jsonb_build_object('outputDigest',repeat('d',64)),pg_temp.background())$$,'P0001','Job/proof/object binding rejected','encoded digest swap rejected atomically');
delete from public.party_members where user_id='66000000-0000-4000-8000-000000000011';
select throws_ok($$select public.complete_map_generation('66000000-0000-4000-8000-000000000004',3,pg_temp.proof(),pg_temp.verified(),pg_temp.background())$$,'42501','Dungeon Master access required','membership loss between prepare and finalize cannot attach');
insert into public.party_members(party_id,user_id,role)values('66000000-0000-4000-8000-000000000001','66000000-0000-4000-8000-000000000011','dungeon-master');
select is(public.complete_map_generation('66000000-0000-4000-8000-000000000004',3,pg_temp.proof(),pg_temp.verified(),pg_temp.background())->>'state','completed','verified output completes via04 atomically');
select is((select count(*)from public.party_map_artwork_versions where family_id='66000000-0000-4000-8000-000000000003'),1::bigint,'one immutable saved version');
select is(public.complete_map_generation('66000000-0000-4000-8000-000000000004',4,pg_temp.proof(),pg_temp.verified(),pg_temp.background())->>'state','completed','same binding recovery reconciles accepted receipt');
select is((select count(*)from public.party_map_presentations where party_id='66000000-0000-4000-8000-000000000001'),0::bigint,'generation never selects display');
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='66000000-0000-4000-8000-000000000011';
select is(jsonb_array_length(public.read_map_generation_jobs()),2,'DM reads semantic job projection');
select ok(not(public.read_map_generation_jobs()->0 ? 'proof'),'DM response excludes private proof');
select throws_ok($$select * from public.party_map_generation_jobs$$,'42501',null,'even DM cannot read raw job ledger');
select throws_ok($$select public.transition_map_generation('66000000-0000-4000-8000-000000000004',4,'cancelled','{}')$$,'42501',null,'client cannot call privileged transition');
set local "request.jwt.claim.sub"='66000000-0000-4000-8000-000000000012';
select throws_ok($$select public.read_map_generation_jobs()$$,'42501','Dungeon Master access required','Player denied job status');
select is((select count(*)from storage.objects where bucket_id='private-map-generation'),0::bigint,'Player known candidate paths denied');
set local role anon;
select throws_ok($$select public.read_map_generation_jobs()$$,'42501',null,'anonymous denied job read');
select is((select count(*)from storage.objects where bucket_id='private-map-generation'),0::bigint,'anonymous candidate path denied');
reset role;
set local "request.jwt.claim.role"='service_role';
update public.party_map_generation_settings set live_enabled=true,spend_cents=0,reservation_cents=10 where party_id='66000000-0000-4000-8000-000000000001';
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent('009'),'live')$$,'P0001','Generation limit reached','zero spend prevents paid reservation even enabled');
update public.party_map_generation_settings set quota=2 where party_id='66000000-0000-4000-8000-000000000001';
select throws_ok($$select public.reserve_map_generation('66000000-0000-4000-8000-000000000011',pg_temp.intent('009'),'fixture')$$,'P0001','Generation limit reached','cumulative quota cannot evade by cancellation');
insert into storage.objects(bucket_id,name,metadata)values('party-handouts','66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000002','{"size":68,"mimetype":"image/png"}'),('private-map-generation','66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000002','{"size":68,"mimetype":"image/png"}');
select is(jsonb_array_length(public.release_map_generation_orphans()),0,'orphan retention cannot delete younger than24hours');
update public.party_map_generation_jobs set updated_at=now()-interval '25 hours' where id='66000000-0000-4000-8000-000000000002';
select is(jsonb_array_length(public.release_map_generation_orphans()),2,'terminal owned orphan list includes both canonical objects');
select is(jsonb_array_length(public.release_map_generation_orphans()),2,'uncertain cleanup response retains durable retry inventory');
select lives_ok($$delete from storage.objects where name='66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000002'$$,'released unaccepted orphans can be removed');
select lives_ok($$select public.ack_map_generation_orphans(array['66000000-0000-4000-8000-000000000002'::uuid])$$,'known cleanup acknowledgement records completion');
select is(jsonb_array_length(public.release_map_generation_orphans()),0,'acknowledged cleanup is idempotent');
select is((select count(*)from storage.objects where name='66000000-0000-4000-8000-000000000001/66000000-0000-4000-8000-000000000004'),2::bigint,'cleanup cannot remove referenced completed output/candidate');
select * from finish();
rollback;
